701	            // If the task IS NOT text, we PREPEND specialized models to avoid Master reasoning hijacking
702	            if (taskType !== 'text') {
703	                const specialized = rolodexModels.filter(rm => !existingSet.has(rm));
704	                rawSequence = [...specialized, ...rawSequence];
705	            } else {
706	                // For text, we append them as fallback to our high-level Config choices
707	                for (const rm of rolodexModels) {
708	                    if (!existingSet.has(rm)) {
