931	    private async syncLocalModels(): Promise<void> {
932	        const now = Date.now();
933	        if (now - this.lastSyncAt < this.SYNC_INTERVAL_MS || this.isSyncing) return;
934	        
935	        this.isSyncing = true;
936	        this.lastSyncAt = now;
937	
