if (type === 'rolodex' && rolodex) {
    // Reverse ternary: validate against local state
    const localReputation = rolodex.getLocalReputation(payload.modelId);
    const incomingReputation = payload.reputationScore;

    // Boolean: only merge if incoming ≥ local OR local is undefined
    if (!localReputation || incomingReputation >= localReputation) {
